import { useEffect, useState } from "react";
import axios from "axios";

import Login from "./components/Login";
import AdminPanel from "./components/AdminPanel";

const API_URL = "http://localhost:5000";

function App() {
  // =======================
  // STATE
  // =======================
  const [candidates, setCandidates] = useState([]);
  const [darkMode, setDarkMode] = useState(false);

  const [auth, setAuth] = useState({
    token: localStorage.getItem("token") || null,
    role: localStorage.getItem("role") || null,
  });

  const [loginForm, setLoginForm] = useState({
    email: "",
    password: "",
  });

  const [candidateForm, setCandidateForm] = useState({
    name: "",
    position: "",
    description: "",
    image: null,
  });

  const [editId, setEditId] = useState(null);
  const [message, setMessage] = useState("");

  // =======================
  // FETCH CANDIDATES
  // =======================
  const fetchCandidates = async () => {
    try {
      const res = await axios.get(`${API_URL}/api/candidates`);
      setCandidates(res.data);
    } catch {
      setMessage("Failed to load candidates.");
    }
  };

  useEffect(() => {
    fetchCandidates();
  }, []);

  // =======================
  // LOGIN
  // =======================
  const handleLogin = async () => {
    try {
      const res = await axios.post(`${API_URL}/api/auth/login`, loginForm);

      localStorage.setItem("token", res.data.token);
      localStorage.setItem("role", res.data.role);

      setAuth({
        token: res.data.token,
        role: res.data.role,
      });

      setMessage("Login successful.");
    } catch {
      setMessage("Invalid email or password.");
    }
  };

  const handleLogout = () => {
    localStorage.removeItem("token");
    localStorage.removeItem("role");
    setAuth({ token: null, role: null });
    setMessage("Logged out successfully.");
  };

  // =======================
  // VOTE
  // =======================
  const handleVote = async (id) => {
    try {
      await axios.post(
        `${API_URL}/api/vote/${id}`,
        {},
        {
          headers: { Authorization: `Bearer ${auth.token}` },
        }
      );

      setMessage("Vote submitted successfully.");
      fetchCandidates();
    } catch {
      setMessage("You already voted or an error occurred.");
    }
  };

  // =======================
  // ADD / EDIT CANDIDATE
  // =======================
  const handleSaveCandidate = async () => {
    try {
      const formData = new FormData();
      formData.append("name", candidateForm.name);
      formData.append("position", candidateForm.position);
      formData.append("description", candidateForm.description);

      if (candidateForm.image) {
        formData.append("image", candidateForm.image);
      }

      if (editId) {
        await axios.put(
          `${API_URL}/api/candidates/${editId}`,
          formData,
          {
            headers: { Authorization: `Bearer ${auth.token}` },
          }
        );
        setMessage("Candidate updated successfully.");
      } else {
        await axios.post(
          `${API_URL}/api/candidates`,
          formData,
          {
            headers: { Authorization: `Bearer ${auth.token}` },
          }
        );
        setMessage("Candidate added successfully.");
      }

      setCandidateForm({
        name: "",
        position: "",
        description: "",
        image: null,
      });
      setEditId(null);
      fetchCandidates();
    } catch {
      setMessage("Failed to save candidate.");
    }
  };

  // =======================
  // DELETE
  // =======================
  const handleDeleteCandidate = async (id) => {
    try {
      await axios.delete(`${API_URL}/api/candidates/${id}`, {
        headers: { Authorization: `Bearer ${auth.token}` },
      });

      setMessage("Candidate deleted.");
      fetchCandidates();
    } catch {
      setMessage("Failed to delete candidate.");
    }
  };

  // =======================
  // THEME
  // =======================
  const theme = {
    background: darkMode ? "#49494b" : "#b7a8a8",
    text: darkMode ? "#e5e7eb" : "#000000",
    card: darkMode ? "#020617" : "#ffffff",
    border: "#1e40af",
    button: "#1e40af",
  };

  // =======================
  // UI
  // =======================
  return (
    <div
      style={{
        maxWidth: 700,
        margin: "auto",
        padding: 20,
        minHeight: "100vh",
        backgroundColor: theme.background,
        color: theme.text,
      }}
    >
      <h1 style={{ textAlign: "center" }}>Online Voting System</h1>

      <button
        onClick={() => setDarkMode(!darkMode)}
        style={{
          marginBottom: 15,
          backgroundColor: theme.button,
          color: "white",
          border: "none",
          padding: "6px 12px",
          borderRadius: 6,
          cursor: "pointer",
        }}
      >
        {darkMode ? "☀ Light Mode" : "🌙 Dark Mode"}
      </button>

      {auth.token && (
        <button
          onClick={handleLogout}
          style={{
            marginLeft: 10,
            backgroundColor: theme.button,
            color: "white",
            border: "none",
            padding: "6px 12px",
            borderRadius: 6,
            cursor: "pointer",
          }}
        >
          Logout
        </button>
      )}

      {message && <p>{message}</p>}

      {!auth.token && (
        <div
          style={{
            border: `2px solid ${theme.border}`,
            padding: 15,
            borderRadius: 8,
            marginBottom: 20,
            backgroundColor: theme.card,
          }}
        >
          <Login
            loginForm={loginForm}
            setLoginForm={setLoginForm}
            onLogin={handleLogin}
          />
        </div>
      )}

      {auth.token && auth.role === "admin" && (
        <div
          style={{
            border: `2px solid ${theme.border}`,
            padding: 15,
            borderRadius: 8,
            marginBottom: 20,
            backgroundColor: theme.card,
          }}
        >
          <AdminPanel
            candidateForm={candidateForm}
            setCandidateForm={setCandidateForm}
            onSave={handleSaveCandidate}
          />
        </div>
      )}

      <section>
        <h2>Candidates</h2>

        {candidates.map((c) => (
          <div
            key={c._id}
            style={{
              border: `2px solid ${theme.border}`,
              padding: 15,
              marginBottom: 12,
              borderRadius: 8,
              backgroundColor: theme.card,
            }}
          >
            <h3>{c.name}</h3>
            <p><strong>Position:</strong> {c.position}</p>
            <p>{c.description}</p>
            <p><strong>Votes:</strong> {c.votes}</p>

            {c.image && (
              <img
                src={`${API_URL}/uploads/${c.image}`}
                alt="candidate"
                width="120"
                style={{ borderRadius: 8 }}
              />
            )}

            {auth.token && auth.role === "user" && (
              <button
                onClick={() => handleVote(c._id)}
                style={{
                  backgroundColor: theme.button,
                  color: "white",
                  border: "none",
                  padding: "6px 12px",
                  borderRadius: 6,
                  cursor: "pointer",
                  marginTop: 8,
                }}
              >
                Vote
              </button>
            )}

            {auth.token && auth.role === "admin" && (
              <div style={{ marginTop: 10 }}>
                <button
                  onClick={() => {
                    setEditId(c._id);
                    setCandidateForm({
                      name: c.name,
                      position: c.position,
                      description: c.description,
                      image: null,
                    });
                  }}
                  style={{
                    backgroundColor: "#16a34a",
                    color: "white",
                    border: "none",
                    padding: "6px 12px",
                    borderRadius: 6,
                    cursor: "pointer",
                    marginRight: 8,
                  }}
                >
                  Edit
                </button>

                <button
                  onClick={() => handleDeleteCandidate(c._id)}
                  style={{
                    backgroundColor: "#dc2626",
                    color: "white",
                    border: "none",
                    padding: "6px 12px",
                    borderRadius: 6,
                    cursor: "pointer",
                  }}
                >
                  Delete
                </button>
              </div>
            )}
          </div>
        ))}
      </section>
    </div>
  );
}

export default App;
